class ApiError extends Error { constructor(status, message, details) { super(message); this.status = status; this.details = details; } }
const assert = (condition, status, message, details) => { if (!condition) throw new ApiError(status, message, details); };
const money = value => { const n = Number(value); assert(Number.isFinite(n) && n >= 0, 400, '金额格式不正确'); return Math.round(n * 100); };
const dateOrNull = value => value ? new Date(value).toISOString() : null;

function json(res, status, payload, headers = {}) {
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store', ...headers });
  res.end(JSON.stringify(payload));
}
function parseCookies(req) {
  return Object.fromEntries((req.headers.cookie || '').split(';').filter(Boolean).map(v => { const i = v.indexOf('='); return [v.slice(0, i).trim(), decodeURIComponent(v.slice(i + 1))]; }));
}
async function body(req) {
  if(req.parsedJsonBody)return req.parsedJsonBody;
  let raw = ''; for await (const chunk of req) { raw += chunk; if (raw.length > 6_000_000) throw new ApiError(413, '请求内容过大'); }
  try { req.parsedJsonBody=raw ? JSON.parse(raw) : {};return req.parsedJsonBody; } catch { throw new ApiError(400, 'JSON 格式无效'); }
}
function currentUser(req) {
  const raw = parseCookies(req).erp_session;
  if (!raw) return null;
  const row = db.prepare(`SELECT s.csrf_token, s.expires_at, u.id, u.company_id, u.email, u.name, u.role, u.department, u.data_scope
    FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.id_hash=? AND s.expires_at>? AND u.active=1`).get(tokenHash(raw), now());
  return row || null;
}
function requireUser(req) { const user = currentUser(req); assert(user, 401, '请先登录'); return user; }
function requireRole(user, roles) { assert(roles.includes(user.role), 403, '当前角色无此操作权限'); }
function requireCsrf(req, user) { assert(req.headers['x-csrf-token'] === user.csrf_token, 403, '安全令牌已失效，请刷新页面'); }
function scopeFilter(user,column){if(user.data_scope==='company')return {sql:'',params:[]};if(user.data_scope==='personal')return {sql:` AND ${column}=?`,params:[user.id]};const ids=db.prepare('SELECT id FROM users WHERE company_id=? AND department=? AND active=1').all(user.company_id,user.department).map(row=>row.id);return {sql:` AND ${column} IN (${ids.map(()=>'?').join(',')||"''"})`,params:ids};}
function canSeeOwner(user,ownerId){if(user.data_scope==='company')return true;if(user.data_scope==='personal')return ownerId===user.id;return Boolean(db.prepare('SELECT id FROM users WHERE id=? AND company_id=? AND department=?').get(ownerId,user.company_id,user.department));}
function objectOwner(user,objectType,objectId){
  const direct={customer:['customers','owner_id'],quote:['quotes','created_by'],sales_order:['sales_orders','created_by'],purchase_order:['purchase_orders','created_by'],delivery_order:['delivery_orders','created_by']}[objectType];
  if(direct)return db.prepare(`SELECT ${direct[1]} owner_id FROM ${direct[0]} WHERE id=? AND company_id=?`).get(objectId,user.company_id)?.owner_id;
  if(objectType==='after_sales')return db.prepare(`SELECT so.created_by owner_id FROM after_sales a JOIN sales_orders so ON so.id=a.sales_order_id WHERE a.id=? AND a.company_id=?`).get(objectId,user.company_id)?.owner_id;
  if(objectType==='finance_entry')return db.prepare(`SELECT so.created_by owner_id FROM finance_entries f JOIN sales_orders so ON so.id=f.sales_order_id WHERE f.id=? AND f.company_id=?`).get(objectId,user.company_id)?.owner_id;
  if(objectType==='performance_share')return db.prepare(`SELECT so.created_by owner_id FROM performance_shares ps JOIN sales_orders so ON so.id=ps.sales_order_id WHERE ps.id=? AND ps.company_id=?`).get(objectId,user.company_id)?.owner_id;
  return null;
}
function assertObjectVisible(user,objectType,objectId){if(user.data_scope==='company')return;const scopedTypes=new Set(['customer','quote','sales_order','purchase_order','delivery_order','after_sales','finance_entry','performance_share']);if(scopedTypes.has(objectType))assert(canSeeOwner(user,objectOwner(user,objectType,objectId)),404,'记录不存在或不在当前数据范围');}
function assertCustomerVisible(user,customerId){const customer=db.prepare('SELECT owner_id FROM customers WHERE id=? AND company_id=? AND deleted_at IS NULL').get(customerId,user.company_id);assert(customer&&canSeeOwner(user,customer.owner_id),404,'客户不存在或不在当前数据范围');}
function match(path, pattern) { const m = path.match(pattern); return m || null; }
function rowPublic(row) {
  if (!row) return row;
  const out = { ...row };
  for (const key of Object.keys(out)) if (key.endsWith('_minor') && typeof out[key] === 'number') out[key.replace('_minor', '')] = out[key] / 100;
  return out;
}
function canReadSensitiveSupplierFields(user){return ['admin','manager','finance'].includes(user.role)}
function maskAccount(value){const text=String(value||'');return text?`****${text.slice(-4)}`:''}
function supplierPublic(user,row){const out=rowPublic(row);if(out&&!canReadSensitiveSupplierFields(user)){out.bank_account=maskAccount(out.bank_account);out.bank_account_masked=out.bank_account}return out}
function supplierList(user,sql,params=[]){return db.prepare(sql).all(...params).map(row=>supplierPublic(user,row))}
function fieldPermissionMatrix(user){const sensitive=canReadSensitiveSupplierFields(user);return {role:user.role,fields:[{module:'供应商',field:'银行账号',read:sensitive?'完整可见':'仅显示尾号',write:'必须发起双人复核变更'},{module:'供应商',field:'开户行',read:'可见',write:'必须发起双人复核变更'},{module:'报价/合同',field:'成本与毛利',read:['admin','manager','finance','sales'].includes(user.role)?'可见':'只读受限',write:['admin','manager','sales'].includes(user.role)?'按角色可编辑':'不可编辑'},{module:'财务',field:'收付款与凭证',read:['admin','manager','finance'].includes(user.role)?'可见':'不可见',write:['admin','finance'].includes(user.role)?'可登记/复核':'不可编辑'},{module:'审批',field:'决定与意见',read:'可见',write:['admin','manager','finance','operations'].includes(user.role)?'仅当前节点可处理':'不可编辑'}]}}
function list(sql, params = []) { return db.prepare(sql).all(...params).map(rowPublic); }
function setting(companyId,key,fallback){const row=db.prepare('SELECT value_json FROM settings WHERE company_id=? AND key=?').get(companyId,key);if(!row)return fallback;try{return JSON.parse(row.value_json)}catch{return fallback}}
const htmlEscape=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
function printableDocument(res,{kind,company,record,customer,items,charges=[]}){const currency=record.currency||'USD';const moneyText=minor=>`${htmlEscape(currency)} ${(Number(minor||0)/100).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}`;const lineRows=items.map((item,index)=>`<tr><td>${index+1}</td><td>${htmlEscape(item.sku||'')}</td><td>${htmlEscape(item.description)}</td><td>${Number(item.quantity).toLocaleString()}</td><td>${moneyText(item.unit_price_minor)}</td><td>${moneyText(Math.round(item.quantity*item.unit_price_minor))}</td></tr>`).join('');const chargeRows=charges.filter(c=>c.category==='revenue').map(c=>`<tr><td colspan="5">${htmlEscape(c.name)}</td><td>${moneyText(c.amount_minor)}</td></tr>`).join('');const title=kind==='PI'?'PROFORMA INVOICE / 形式发票':'SALES CONTRACT / 销售合同';const number=record.document_no;const issue=String(record.created_at||now()).slice(0,10);const content=`<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><title>${htmlEscape(number)} · ${title}</title><style>@page{size:A4;margin:14mm}*{box-sizing:border-box}body{font:12px Arial,"PingFang SC",sans-serif;color:#17231e;margin:0}.head{display:flex;justify-content:space-between;border-bottom:3px solid #173f32;padding-bottom:18px}.brand{font:bold 25px Georgia;color:#173f32}.kind{text-align:right}.kind h1{font-size:20px;margin:0 0 8px}.meta,.parties{display:grid;grid-template-columns:1fr 1fr;gap:24px;margin:22px 0}.box{border:1px solid #cad2cd;padding:14px}.box small{color:#728078;text-transform:uppercase}.box p{margin:7px 0 0;line-height:1.6}table{width:100%;border-collapse:collapse;margin:18px 0}th,td{border:1px solid #cad2cd;padding:9px;text-align:left}th{background:#173f32;color:white;font-size:10px}td:nth-last-child(-n+3){text-align:right}.total{display:flex;justify-content:flex-end}.total div{width:290px;border:2px solid #173f32;padding:14px;display:flex;justify-content:space-between;font-size:16px}.terms{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:22px}.footer{margin-top:50px;display:grid;grid-template-columns:1fr 1fr;gap:80px}.sign{border-top:1px solid #17231e;padding-top:8px;color:#728078}@media print{.no-print{display:none}}</style></head><body><div class="head"><div><div class="brand">${htmlEscape(company.name)}</div><p>GLOBAL TRADE OPERATING SYSTEM</p></div><div class="kind"><h1>${title}</h1><strong>${htmlEscape(number)}</strong></div></div><div class="meta"><div class="box"><small>Issue Date / 出具日期</small><p>${issue}</p></div><div class="box"><small>Validity / 有效期</small><p>${htmlEscape(String(record.valid_until||record.delivery_at||'—').slice(0,10))}</p></div></div><div class="parties"><div class="box"><small>Seller / 卖方</small><p><strong>${htmlEscape(company.name)}</strong></p></div><div class="box"><small>Buyer / 买方</small><p><strong>${htmlEscape(customer.name)}</strong><br>${htmlEscape(customer.contact_name||'')}<br>${htmlEscape(customer.country||'')}</p></div></div><table><thead><tr><th>#</th><th>SKU</th><th>Description / 产品描述</th><th>Qty / 数量</th><th>Unit Price / 单价</th><th>Amount / 金额</th></tr></thead><tbody>${lineRows}${chargeRows}</tbody></table><div class="total"><div><strong>Total / 合计</strong><strong>${moneyText(record.amount_minor)}</strong></div></div><div class="terms"><div class="box"><small>Trade Terms / 贸易条款</small><p>${htmlEscape(record.incoterm||'—')}</p></div><div class="box"><small>Payment Terms / 付款条款</small><p>${htmlEscape(record.payment_terms||'—')}</p></div><div class="box"><small>Delivery / 交期</small><p>${htmlEscape(String(record.delivery_at||'—').slice(0,10))}</p></div><div class="box"><small>Notes / 备注</small><p>${htmlEscape(record.notes||'—')}</p></div></div><div class="footer"><div class="sign">Seller Signature / 卖方签章</div><div class="sign">Buyer Signature / 买方签章</div></div></body></html>`;res.writeHead(200,{'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-store','Content-Disposition':`inline; filename="${number}.html"`,'X-Content-Type-Options':'nosniff','X-Frame-Options':'SAMEORIGIN'});res.end(content);}

function recordEvent(user, objectType, objectId, eventType, fromStatus = null, toStatus = null, note = '') {
  db.prepare('INSERT INTO business_events VALUES (?,?,?,?,?,?,?,?,?,?)')
    .run(id('event'), user.company_id, objectType, objectId, eventType, fromStatus, toStatus, note, user.id, now());
}

function createApproval(user, objectType, objectId, objectVersion, reason, assignedRoles = ['manager']) {
  const roles = Array.isArray(assignedRoles) ? assignedRoles : [assignedRoles];
  assert(roles.length > 0, 500, '审批流程没有配置节点');
  const approvalId = id('approval');
  db.prepare(`INSERT INTO approvals VALUES (?, ?, ?, ?, ?, ?, ?, 'pending', ?, ?, NULL, NULL, ?, NULL)`)
    .run(approvalId, user.company_id, docNo('AP'), objectType, objectId, objectVersion, reason, user.id, roles[0], now());
  const insertStep = db.prepare('INSERT INTO approval_steps VALUES (?,?,?,?,?,?,?,?)');
  roles.forEach((role, index) => insertStep.run(id('step'), approvalId, index + 1, role, index === 0 ? 'pending' : 'waiting', null, null, null));
  const approvers=db.prepare('SELECT id FROM users WHERE company_id=? AND active=1 AND role IN (?,?)').all(user.company_id,roles[0],'admin');
  const insertNotification=db.prepare('INSERT INTO notifications VALUES (?,?,?,?,?,?,?,?,?,?,?)');
  for(const approver of approvers)if(approver.id!==user.id)insertNotification.run(id('notice'),user.company_id,approver.id,'approval_todo','新的审批待办',reason,'approval',approvalId,'high',null,now());
  recordEvent(user, objectType, objectId, 'approval_requested', null, 'approval_pending', reason);
  return approvalId;
}

function workflowData(user, objectType, objectId) {
  return {
    events: list(`SELECT e.*,u.name created_by_name FROM business_events e JOIN users u ON u.id=e.created_by WHERE e.company_id=? AND e.object_type=? AND e.object_id=? ORDER BY e.created_at DESC`, [user.company_id, objectType, objectId]),
    approvals: list(`SELECT a.*,u.name requester_name,d.name decider_name FROM approvals a JOIN users u ON u.id=a.requested_by LEFT JOIN users d ON d.id=a.decided_by WHERE a.company_id=? AND a.object_type IN (?,?) AND a.object_id=? ORDER BY a.created_at DESC`, [user.company_id, objectType, `${objectType}_void`, objectId]),
    audit: list(`SELECT a.*,u.name user_name FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id WHERE a.company_id=? AND a.object_type=? AND a.object_id=? ORDER BY a.created_at DESC LIMIT 50`, [user.company_id, objectType, objectId])
  };
}

function approvalBusinessSummary(user,approval){
  const type=String(approval.object_type||'').replace(/_void$/,'');let row;
  if(type==='quote')row=db.prepare(`SELECT q.document_no,c.name counterparty,q.amount_minor,q.currency,q.margin_bps,q.status FROM quotes q JOIN customers c ON c.id=q.customer_id WHERE q.id=? AND q.company_id=?`).get(approval.object_id,user.company_id);
  else if(type==='sales_order')row=db.prepare(`SELECT so.document_no,c.name counterparty,so.amount_minor,so.currency,so.status FROM sales_orders so JOIN customers c ON c.id=so.customer_id WHERE so.id=? AND so.company_id=?`).get(approval.object_id,user.company_id);
  else if(type==='purchase_order')row=db.prepare(`SELECT po.document_no,s.name counterparty,po.amount_minor,po.currency,po.status FROM purchase_orders po JOIN suppliers s ON s.id=po.supplier_id WHERE po.id=? AND po.company_id=?`).get(approval.object_id,user.company_id);
  else if(type==='delivery_order')row=db.prepare(`SELECT d.document_no,d.forwarder counterparty,d.freight_minor amount_minor,d.currency,d.status FROM delivery_orders d WHERE d.id=? AND d.company_id=?`).get(approval.object_id,user.company_id);
  else if(type==='performance_share')row=db.prepare(`SELECT ps.document_no,u.name counterparty,ps.amount_base_minor amount_minor,'CNY' currency,ps.status FROM performance_shares ps JOIN users u ON u.id=ps.beneficiary_id WHERE ps.id=? AND ps.company_id=?`).get(approval.object_id,user.company_id);
  else if(type==='supplier_bank_change')row=db.prepare(`SELECT '付款账户变更' document_no,s.name counterparty,sbc.status,sbc.new_bank_name detail FROM supplier_bank_changes sbc JOIN suppliers s ON s.id=sbc.supplier_id WHERE sbc.id=? AND sbc.company_id=?`).get(approval.object_id,user.company_id);
  else if(type==='performance_reallocation'){row=db.prepare(`SELECT document_no,status,summary_json FROM performance_reallocations WHERE id=? AND company_id=?`).get(approval.object_id,user.company_id);if(row?.summary_json){const summary=JSON.parse(row.summary_json);row.counterparty=`${summary.contractCount} 份合同 / ${summary.shareCount} 条分配`;row.amount_minor=Math.round(summary.newTotal*100);row.currency='CNY';row.detail=`差异 ${summary.delta>=0?'+':''}${summary.delta.toFixed(2)}`;delete row.summary_json;}}
  return rowPublic(row)||{document_no:approval.object_id,counterparty:'业务记录'};
}

function createSchedule(user, { objectType, objectId, direction, label, dueAt, currency, amountMinor, sequenceNo = 1 }) {
  if (!amountMinor || amountMinor <= 0) return null;
  const existing = db.prepare(`SELECT id FROM payment_schedules WHERE company_id=? AND object_type=? AND object_id=? AND direction=? AND sequence_no=?`).get(user.company_id, objectType, objectId, direction, sequenceNo);
  if (existing) return existing.id;
  const scheduleId=id('schedule');
  db.prepare(`INSERT INTO payment_schedules VALUES (?,?,?,?,?,?,?,?,?,?,0,'outstanding',?,?,?,?)`).run(scheduleId,user.company_id,docNo(direction==='receivable'?'AR':'AP'),objectType,objectId,direction,label,dueAt||null,currency,amountMinor,sequenceNo,user.id,now(),now());
  return scheduleId;
}

function recalculateSchedule(scheduleId) {
  const schedule=db.prepare('SELECT * FROM payment_schedules WHERE id=?').get(scheduleId);if(!schedule)return;
  const paid=db.prepare(`SELECT COALESCE(SUM(a.amount_minor),0) value FROM finance_allocations a JOIN finance_entries f ON f.id=a.finance_entry_id WHERE a.schedule_id=? AND f.status='confirmed'`).get(scheduleId).value;
  const nextPaid=Math.min(schedule.amount_minor,paid);
  const statusValue=nextPaid>=schedule.amount_minor?'paid':nextPaid>0?'partial':'outstanding';
  db.prepare('UPDATE payment_schedules SET paid_minor=?,status=?,updated_at=? WHERE id=?').run(nextPaid,statusValue,now(),scheduleId);
}

function allocateConfirmedEntry(entryId) {
  const allocations=db.prepare('SELECT schedule_id FROM finance_allocations WHERE finance_entry_id=?').all(entryId);
  for(const allocation of allocations)recalculateSchedule(allocation.schedule_id);
}

function scheduleExchangeRate(schedule) {
  if(!schedule||schedule.currency==='CNY')return 1;
  if(schedule.object_type==='sales_order')return Number(db.prepare('SELECT exchange_rate FROM sales_orders WHERE id=?').get(schedule.object_id)?.exchange_rate||1);
  if(schedule.object_type==='purchase_order')return Number(db.prepare('SELECT so.exchange_rate FROM purchase_orders po JOIN sales_orders so ON so.id=po.sales_order_id WHERE po.id=?').get(schedule.object_id)?.exchange_rate||1);
  if(schedule.object_type==='delivery_order')return Number(db.prepare('SELECT so.exchange_rate FROM delivery_orders d JOIN sales_orders so ON so.id=d.sales_order_id WHERE d.id=?').get(schedule.object_id)?.exchange_rate||1);
  return 1;
}

function scheduleRows(user, direction) {
  const rows=list(`SELECT s.*,
    CASE s.object_type WHEN 'sales_order' THEN (SELECT so.document_no||' · '||c.name FROM sales_orders so JOIN customers c ON c.id=so.customer_id WHERE so.id=s.object_id)
      WHEN 'purchase_order' THEN (SELECT po.document_no||' · '||sp.name FROM purchase_orders po JOIN suppliers sp ON sp.id=po.supplier_id WHERE po.id=s.object_id)
      WHEN 'delivery_order' THEN (SELECT d.document_no||' · '||d.forwarder FROM delivery_orders d WHERE d.id=s.object_id)
      WHEN 'performance_share' THEN (SELECT ps.document_no||' · '||u.name FROM performance_shares ps JOIN users u ON u.id=ps.beneficiary_id WHERE ps.id=s.object_id)
      ELSE s.object_id END object_label,
    CASE s.object_type WHEN 'sales_order' THEN (SELECT exchange_rate FROM sales_orders WHERE id=s.object_id)
      WHEN 'purchase_order' THEN (SELECT so.exchange_rate FROM purchase_orders po JOIN sales_orders so ON so.id=po.sales_order_id WHERE po.id=s.object_id)
      WHEN 'delivery_order' THEN (SELECT CASE WHEN d.currency='CNY' THEN 1 ELSE so.exchange_rate END FROM delivery_orders d JOIN sales_orders so ON so.id=d.sales_order_id WHERE d.id=s.object_id)
      ELSE 1 END object_exchange_rate,
    CASE s.object_type WHEN 'sales_order' THEN (SELECT created_by FROM sales_orders WHERE id=s.object_id)
      WHEN 'purchase_order' THEN (SELECT so.created_by FROM purchase_orders po JOIN sales_orders so ON so.id=po.sales_order_id WHERE po.id=s.object_id)
      WHEN 'delivery_order' THEN (SELECT so.created_by FROM delivery_orders d JOIN sales_orders so ON so.id=d.sales_order_id WHERE d.id=s.object_id)
      WHEN 'performance_share' THEN (SELECT so.created_by FROM performance_shares ps JOIN sales_orders so ON so.id=ps.sales_order_id WHERE ps.id=s.object_id)
      ELSE s.created_by END owner_id
    FROM payment_schedules s WHERE s.company_id=? AND s.direction=? AND s.status!='void' ORDER BY CASE WHEN s.status='paid' THEN 1 ELSE 0 END,s.due_at,s.created_at DESC`,[user.company_id,direction]);
  return rows.filter(row=>canSeeOwner(user,row.owner_id)).map(row=>{const outstanding=(row.amount_minor-row.paid_minor)/100;return {...row,outstanding,baseOutstanding:outstanding*Number(row.object_exchange_rate||1),overdueDays:row.status!=='paid'&&row.due_at?Math.max(0,Math.floor((Date.now()-new Date(row.due_at).getTime())/86400000)):0}});
}

function reallocationPreview(user,input) {
  const month=String(input.month||''),allocations=Array.isArray(input.allocations)?input.allocations:[];assert(/^\d{4}-\d{2}$/.test(month),400,'重分配月份无效');assert(allocations.length>0&&allocations.length<=200,400,'请选择 1 至 200 条被驳回的分成记录');assert(new Set(allocations.map(x=>x.shareId)).size===allocations.length,400,'分成记录不能重复');const changes=[];
  for(const item of allocations){const share=db.prepare(`SELECT ps.*,u.name beneficiary_name,so.document_no sales_order_no FROM performance_shares ps JOIN users u ON u.id=ps.beneficiary_id JOIN sales_orders so ON so.id=ps.sales_order_id WHERE ps.id=? AND ps.company_id=?`).get(item.shareId,user.company_id);assert(share,404,'分成记录不存在');assert(share.status==='rejected',409,`${share.document_no} 不是已驳回状态，不能在原方案重分配`);assert((share.application_month||share.created_at.slice(0,7))===month,422,`${share.document_no} 不属于 ${month}`);const beneficiary=db.prepare('SELECT id,name,role FROM users WHERE id=? AND company_id=? AND active=1').get(item.beneficiaryId,user.company_id);assert(beneficiary,404,'新分配人员不存在或已停用');const profit=calculateProfit(share.sales_order_id);assert(profit.grossProfit>0,422,`${share.sales_order_no} 当前没有正毛利`);const amount=Number(item.amount)>0?money(item.amount):Math.round(profit.grossProfit*100*Number(item.percent||0)/100);assert(amount>0,400,'重分配金额或比例必须大于 0');const allocationBps=Math.round(amount/(profit.grossProfit*100)*10000);changes.push({shareId:share.id,documentNo:share.document_no,salesOrderId:share.sales_order_id,salesOrderNo:share.sales_order_no,oldBeneficiaryId:share.beneficiary_id,oldBeneficiaryName:share.beneficiary_name,newBeneficiaryId:beneficiary.id,newBeneficiaryName:beneficiary.name,newDepartmentRole:beneficiary.role,oldAmountMinor:share.amount_base_minor,newAmountMinor:amount,oldAllocationBps:share.allocation_bps||0,newAllocationBps:allocationBps,deltaMinor:amount-share.amount_base_minor,profitMinor:Math.round(profit.grossProfit*100)});}
  for(const orderId of new Set(changes.map(x=>x.salesOrderId))){const profit=calculateProfit(orderId),existing=db.prepare(`SELECT COALESCE(SUM(amount_base_minor),0) value FROM performance_shares WHERE sales_order_id=? AND status NOT IN ('void','rejected')`).get(orderId).value,proposed=changes.filter(x=>x.salesOrderId===orderId).reduce((n,x)=>n+x.newAmountMinor,0),limit=Math.round(profit.grossProfit*100*setting(user.company_id,'max_share_ratio_bps',4000)/10000);assert(existing+proposed<=limit,422,`${changes.find(x=>x.salesOrderId===orderId).salesOrderNo} 重分配后超过员工分配上限`);}
  const oldTotalMinor=changes.reduce((n,x)=>n+x.oldAmountMinor,0),newTotalMinor=changes.reduce((n,x)=>n+x.newAmountMinor,0);return {month,changes,summary:{shareCount:changes.length,contractCount:new Set(changes.map(x=>x.salesOrderId)).size,oldTotal:oldTotalMinor/100,newTotal:newTotalMinor/100,delta:(newTotalMinor-oldTotalMinor)/100,peopleBefore:new Set(changes.map(x=>x.oldBeneficiaryId)).size,peopleAfter:new Set(changes.map(x=>x.newBeneficiaryId)).size}};
}

function preparePerformanceShare(user,input) {
  const x={...input};assert(x.salesOrderId&&x.beneficiaryId,400,'合同和受益人必填');
  const month=x.applicationMonth||now().slice(0,7);assert(/^\d{4}-\d{2}$/.test(month),400,'申请月份格式无效');
  const order=db.prepare(`SELECT id,document_no FROM sales_orders WHERE id=? AND company_id=? AND deleted_at IS NULL AND document_status='effective'`).get(x.salesOrderId,user.company_id);assert(order,422,'销售合同不存在、未生效或已作废');
  const beneficiary=db.prepare('SELECT id,name FROM users WHERE id=? AND company_id=? AND active=1').get(x.beneficiaryId,user.company_id);assert(beneficiary,404,'受益人不存在或已停用');
  const profit=calculateProfit(x.salesOrderId);assert(profit&&profit.grossProfit>0,422,`${order.document_no} 当前没有可分配正毛利`);
  const percent=Number(x.percent||0),amount=Number(x.amount)>0?money(x.amount):Math.round(profit.grossProfit*100*percent/100);assert(amount>0,400,'分配金额或比例必须大于 0');
  const allocationBps=Math.round(amount/(profit.grossProfit*100)*10000),existing=db.prepare(`SELECT COALESCE(SUM(amount_base_minor),0) v FROM performance_shares WHERE sales_order_id=? AND status NOT IN ('void','rejected')`).get(x.salesOrderId).v,ratio=setting(user.company_id,'max_share_ratio_bps',4000)/10000;
  assert(existing+amount<=Math.round(profit.grossProfit*100*ratio),422,`${order.document_no} 员工分配累计不得超过当前毛利的 ${(ratio*100).toFixed(0)}%`);
  return {x,month,amount,allocationBps,order,beneficiary};
}

function insertPerformanceShare(user,prepared) {
  const {x,month,amount,allocationBps}=prepared,sid=id('share');
  db.prepare(`INSERT INTO performance_shares (id,company_id,document_no,sales_order_id,beneficiary_id,amount_base_minor,status,created_by,created_at,updated_at,application_month,customer_confirmed_at,allocation_bps,notes,evidence_ref) VALUES (?,?,?,?,?,?,'approval_pending',?,?,?,?,?,?,?,?)`).run(sid,user.company_id,docNo('PS'),x.salesOrderId,x.beneficiaryId,amount,user.id,now(),now(),month,dateOrNull(x.customerConfirmedAt),allocationBps,String(x.notes||''),String(x.evidenceRef||''));
  createApproval(user,'performance_share',sid,1,`业绩分成申请 · ${month} · ${(allocationBps/100).toFixed(2)}%`,['operations','finance']);
  audit({companyId:user.company_id,userId:user.id,action:'create',objectType:'performance_share',objectId:sid,after:{...x,month,amount,allocationBps}});
  return {id:sid,amount:amount/100,allocationPercent:allocationBps/100};
}

function monthlyAllocationReport(user,month) {
  assert(/^\d{4}-\d{2}$/.test(String(month||'')),400,'月份格式无效');
  const rows=list(`SELECT ps.*,so.document_no sales_order_no,c.name customer_name,u.name beneficiary_name,u.role department_role,s.status settlement_status FROM performance_shares ps JOIN sales_orders so ON so.id=ps.sales_order_id JOIN customers c ON c.id=so.customer_id JOIN users u ON u.id=ps.beneficiary_id LEFT JOIN payment_schedules s ON s.object_type='performance_share' AND s.object_id=ps.id AND s.status!='void' WHERE ps.company_id=? AND COALESCE(ps.application_month,substr(ps.created_at,1,7))=? AND ps.status NOT IN ('void','rejected') ORDER BY u.name,so.document_no`,[user.company_id,month]);
  const orderIds=[...new Set(rows.map(row=>row.sales_order_id))],profits=new Map(orderIds.map(orderId=>[orderId,calculateProfit(orderId)]));
  const contracts=orderIds.map(orderId=>{const lines=rows.filter(row=>row.sales_order_id===orderId),profit=profits.get(orderId),allocated=lines.reduce((sum,row)=>sum+Number(row.amount_base||0),0);return {salesOrderId:orderId,salesOrderNo:lines[0].sales_order_no,customerName:lines[0].customer_name,revenue:profit.revenue,grossProfit:profit.grossProfit,allocated,companyRetained:profit.grossProfit-allocated}});
  const people=Object.values(rows.reduce((map,row)=>{if(!map[row.beneficiary_id])map[row.beneficiary_id]={beneficiaryId:row.beneficiary_id,beneficiaryName:row.beneficiary_name,departmentRole:row.department_role,allocated:0,contractIds:new Set(),shareCount:0};const person=map[row.beneficiary_id];person.allocated+=Number(row.amount_base||0);person.contractIds.add(row.sales_order_id);person.shareCount++;return map},{})).map(person=>({...person,contractCount:person.contractIds.size,contractIds:undefined})).sort((a,b)=>b.allocated-a.allocated);
  const revenue=contracts.reduce((sum,row)=>sum+row.revenue,0),grossProfit=contracts.reduce((sum,row)=>sum+row.grossProfit,0),allocated=rows.reduce((sum,row)=>sum+Number(row.amount_base||0),0),companyRetained=grossProfit-allocated,champion=people[0]||null;
  return {month,summary:{contractCount:contracts.length,shareCount:rows.length,peopleCount:people.length,revenue,grossProfit,allocated,companyRetained,averageRetentionPercent:grossProfit?companyRetained/grossProfit*100:0,championName:champion?.beneficiaryName||'—',championAmount:champion?.allocated||0,people5To10k:people.filter(person=>person.allocated>=5000&&person.allocated<10000).length,people10kPlus:people.filter(person=>person.allocated>=10000).length},people,contracts,rows};
}

function sendMonthlyAllocationPrint(res,report){const moneyValue=value=>`CNY ${Number(value||0).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2})}`,rows=report.rows.map(row=>`<tr><td>${htmlEscape(row.sales_order_no)}</td><td>${htmlEscape(row.document_no)}</td><td>${htmlEscape(row.beneficiary_name)}</td><td>${(Number(row.allocation_bps||0)/100).toFixed(2)}%</td><td>${moneyValue(row.amount_base)}</td><td>${htmlEscape(row.status)}</td><td>${htmlEscape(row.settlement_status||'unpaid')}</td></tr>`).join(''),s=report.summary;const html=`<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><title>${htmlEscape(report.month)} 月度完整分配表</title><style>@page{size:A4 landscape;margin:10mm}body{font:12px Arial,"PingFang SC",sans-serif;color:#17231e}.head{border-bottom:3px solid #173f31;padding-bottom:14px}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:9px;margin:14px 0}.card{border:1px solid #cbd4ce;padding:10px}.card small{color:#697970}.card strong{display:block;font-size:16px;margin-top:6px}table{width:100%;border-collapse:collapse}th{background:#173f31;color:#fff}th,td{border:1px solid #b9c3bd;padding:7px;text-align:left}.no-print{border:0;border-radius:7px;background:#173f31;color:#fff;padding:9px 14px}@media print{.no-print{display:none}}</style></head><body><button class="no-print" onclick="print()">打印 / 另存为 PDF</button><div class="head"><h1>航贸云 · ${htmlEscape(report.month)} 月度完整分配表</h1><p>${s.contractCount} 份合同 · ${s.peopleCount} 人 · ${s.shareCount} 条分配</p></div><div class="cards"><div class="card"><small>确认收入</small><strong>${moneyValue(s.revenue)}</strong></div><div class="card"><small>最终毛利</small><strong>${moneyValue(s.grossProfit)}</strong></div><div class="card"><small>员工分配</small><strong>${moneyValue(s.allocated)}</strong></div><div class="card"><small>公司留存</small><strong>${moneyValue(s.companyRetained)} · ${s.averageRetentionPercent.toFixed(2)}%</strong></div><div class="card"><small>本月冠军</small><strong>${htmlEscape(s.championName)} · ${moneyValue(s.championAmount)}</strong></div><div class="card"><small>单人 5K–10K</small><strong>${s.people5To10k} 人</strong></div><div class="card"><small>单人 10K+</small><strong>${s.people10kPlus} 人</strong></div></div><table><thead><tr><th>SO</th><th>PS</th><th>人员</th><th>比例</th><th>金额</th><th>审批</th><th>结算</th></tr></thead><tbody>${rows}</tbody></table></body></html>`;res.writeHead(200,{'Content-Type':'text/html; charset=utf-8','Content-Disposition':'inline','Cache-Control':'no-store','X-Frame-Options':'SAMEORIGIN'});res.end(html)}

function monthRange(value){const month=/^\d{4}-\d{2}$/.test(String(value||''))?String(value):now().slice(0,7),start=`${month}-01T00:00:00.000Z`,next=new Date(`${start}`);next.setUTCMonth(next.getUTCMonth()+1);return {month,start,end:next.toISOString()};}

function dashboard(user,period) {
  const company = user.company_id;
  const range=monthRange(period);
  const scalar = (sql, ...params) => db.prepare(sql).get(...params).value;
  const customerScope=scopeFilter(user,'c.owner_id'),orderScope=scopeFilter(user,'so.created_by');
  const cash=list(`SELECT f.type,f.base_amount_minor FROM finance_entries f JOIN sales_orders so ON so.id=f.sales_order_id WHERE f.company_id=? AND f.status='confirmed' AND f.created_at>=? AND f.created_at<?${orderScope.sql}`,[company,range.start,range.end,...orderScope.params]);
  const revenue=cash.filter(row=>row.type==='receipt').reduce((n,row)=>n+row.base_amount_minor,0),payments=cash.filter(row=>['payment','refund'].includes(row.type)).reduce((n,row)=>n+row.base_amount_minor,0);
  const schedules=[...scheduleRows(user,'receivable'),...scheduleRows(user,'payable')];
  return {
    metrics: {
      customers: scalar(`SELECT COUNT(*) value FROM customers c WHERE c.company_id=? AND c.deleted_at IS NULL${customerScope.sql}`,company,...customerScope.params),
      activeOrders: scalar(`SELECT COUNT(*) value FROM sales_orders so WHERE so.company_id=? AND so.deleted_at IS NULL AND so.status!='closed'${orderScope.sql}`,company,...orderScope.params),
      newOrders: scalar(`SELECT COUNT(*) value FROM sales_orders so WHERE so.company_id=? AND so.deleted_at IS NULL AND so.created_at>=? AND so.created_at<?${orderScope.sql}`,company,range.start,range.end,...orderScope.params),
      receivableOutstanding: schedules.filter(row=>row.direction==='receivable').reduce((n,row)=>n+row.baseOutstanding,0),
      cashPayments: payments/100,
      pendingApprovals: scalar(`SELECT COUNT(*) value FROM approvals WHERE company_id=? AND status='pending'`, company),
      unreadNotifications: scalar(`SELECT COUNT(*) value FROM notifications WHERE company_id=? AND (user_id IS NULL OR user_id=?) AND read_at IS NULL`, company,user.id)
        + scalar(`SELECT COUNT(*) value FROM customers c WHERE c.company_id=? AND c.deleted_at IS NULL AND c.status='active' AND c.next_followup_at<?${customerScope.sql}`,company,now(),...customerScope.params)
        + schedules.filter(row=>row.status!=='paid'&&row.due_at&&row.due_at<now()).length,
      revenue: revenue / 100, grossCash: (revenue - payments) / 100
    },
    pipeline: list(`SELECT c.stage label,COUNT(*) value FROM customers c WHERE c.company_id=? AND c.deleted_at IS NULL${customerScope.sql} GROUP BY c.stage`,[company,...customerScope.params]),
    recentOrders: list(`SELECT so.*,c.name customer_name FROM sales_orders so JOIN customers c ON c.id=so.customer_id WHERE so.company_id=? AND so.deleted_at IS NULL${orderScope.sql} ORDER BY so.created_at DESC LIMIT 6`,[company,...orderScope.params]),
    pending: list(`SELECT a.*, u.name requester_name FROM approvals a JOIN users u ON u.id=a.requested_by WHERE a.company_id=? AND a.status='pending' ORDER BY a.created_at DESC LIMIT 6`, [company]),
    period:range.month
  };
}

function assistantReply(query){
  const q=String(query||'').trim();assert(q&&q.length<=300,400,'请输入 1 至 300 个字的系统操作问题');
  const rules=[
    [/客户|跟进|crm/i,{title:'客户与跟进',view:'customers',steps:['进入“客户与跟进”','用国家、等级、阶段或负责人筛选客户','打开客户详情查看报价、合同与业务轨迹','点击“记录跟进”填写结果、下一动作和下次跟进时间']}],
    [/报价|\bpi\b|毛利/i,{title:'报价与 PI',view:'quotes',steps:['进入“报价管理”并创建报价','选择客户，逐行添加产品、数量、售价和成本','确认汇率、贸易条款、付款条款、交期与费用','检查毛利后提交；低毛利会自动进入审批','生效后可打印 PI 或转为销售合同']}],
    [/合同|\bso\b/i,{title:'销售合同',view:'orders',steps:['进入“销售合同”','可由已生效 PI 转入，也可直接新建','核对多产品明细、金额、条款和交期后提交审批','审批生效后系统生成应收并进入采购、出运履约']}],
    [/采购|\bpo\b/i,{title:'采购管理',view:'purchases',steps:['先确认销售合同已经生效','进入“采购管理”查看待采购池','选择合同、供应商和合同明细，填写数量、价格、税率与付款节奏','提交经理和财务审批；通过后生成应付']}],
    [/出运|发货|物流|\bdo\b/i,{title:'出运管理',view:'deliveries',steps:['先确认销售合同已经生效','进入“出运管理”查看待出运池','填写货代、运输方式、包装、箱数、重量、体积、运费和计划日期','提交经理和运营审批；通过后生成物流应付']}],
    [/收款|付款|应收|应付|财务|冲正/i,{title:'应收应付',view:'finance',steps:['进入“应收应付”选择待收或待付计划','核对关联 SO、PO、DO 或 PS 与未结金额','填写币种、金额、结算汇率、渠道和凭证号','大额付款需要复核；发现错误使用冲正，不能直接删除流水']}],
    [/利润|分成|提成|\bps\b/i,{title:'利润与提成',view:'shares',steps:['进入“利润与提成”并选择业务月份','先核对合同实际收入、成本、退款和毛利','按人员填写分配比例或金额并上传/引用证明','提交运营和财务审批；通过后进入待付款']}],
    [/审批|同意|驳回|撤回/i,{title:'审批中心',view:'approvals',steps:['进入“审批中心”查看“我的待办”','打开审批查看业务摘要、完整资料、附件与节点','填写判断依据后同意或驳回','申请人可在审批完成前撤回，修改业务单据后重新提交']}],
    [/权限|数据范围|个人|部门|全公司/i,{title:'数据范围',view:'dashboard',steps:['在页面右上角选择个人、部门或全公司范围','个人范围只显示本人负责或创建的数据','部门范围显示同部门在职成员数据','只有获授权角色可以查看全公司数据']}],
    [/附件|凭证|上传/i,{title:'附件与凭证',view:'notifications',steps:['打开对应客户、单据、审批或财务记录详情','点击“上传附件”选择 PDF、图片、CSV、Word 或 Excel','上传后系统记录文件摘要、上传人和审计日志','下载权限跟随业务记录的数据范围']}]
  ];
  const found=rules.find(([pattern])=>pattern.test(q));
  if(!found)return {inScope:false,title:'仅支持航贸云操作问题',answer:'我只能说明航贸云里的页面、字段和操作步骤，不提供市场判断、客户决策、合同法律意见，也不会替你新增、修改、审批或付款。你可以问：“如何创建 PI？”“付款怎么冲正？”“部门数据范围是什么意思？”'};
  const item=found[1];return {inScope:true,title:item.title,view:item.view,answer:item.steps.map((step,index)=>`${index+1}. ${step}`).join('\n')};
}

function selectedIds(url){const ids=[...new Set(String(url.searchParams.get('ids')||'').split(',').map(value=>value.trim()).filter(Boolean))];assert(ids.length>0&&ids.length<=500,400,'请选择 1 至 500 条记录');return ids;}
