    quotes:{sql:`SELECT q.*,c.name customer_name FROM quotes q JOIN customers c ON c.id=q.customer_id WHERE q.company_id=? AND q.deleted_at IS NULL`,alias:'q',owner:'q.created_by',columns:[['PI编号','document_no'],['客户','customer_name'],['币种','currency'],['金额','amount'],['成本','cost'],['毛利率基点','margin_bps'],['贸易条款','incoterm'],['付款条款','payment_terms'],['有效期','valid_until'],['交期','delivery_at'],['状态','status']]},
    orders:{sql:`SELECT so.*,c.name customer_name FROM sales_orders so JOIN customers c ON c.id=so.customer_id WHERE so.company_id=? AND so.deleted_at IS NULL`,alias:'so',owner:'so.created_by',columns:[['SO编号','document_no'],['客户','customer_name'],['币种','currency'],['金额','amount'],['贸易条款','incoterm'],['付款条款','payment_terms'],['交期','delivery_at'],['状态','status'],['单据状态','document_status']]},
    purchases:{sql:`SELECT po.*,so.document_no sales_order_no,s.name supplier_name FROM purchase_orders po JOIN sales_orders so ON so.id=po.sales_order_id JOIN suppliers s ON s.id=po.supplier_id WHERE po.company_id=? AND po.deleted_at IS NULL`,alias:'po',owner:'po.created_by',columns:[['PO编号','document_no'],['SO编号','sales_order_no'],['供应商','supplier_name'],['币种','currency'],['金额','amount'],['采购日期','ordered_at'],['预计交期','expected_at'],['采购方式','procurement_method'],['状态','status'],['单据状态','document_status']]},
    deliveries:{sql:`SELECT d.*,so.document_no sales_order_no FROM delivery_orders d JOIN sales_orders so ON so.id=d.sales_order_id WHERE d.company_id=? AND d.deleted_at IS NULL`,alias:'d',owner:'d.created_by',columns:[['DO编号','document_no'],['SO编号','sales_order_no'],['货代','forwarder'],['运输方式','transport_mode'],['追踪号','tracking_no'],['币种','currency'],['运费','freight'],['计划出运','planned_at'],['实际出运','shipped_at'],['状态','status'],['单据状态','document_status']]},
    approvals:{sql:`SELECT a.*,u.name requester_name,d.name decider_name FROM approvals a JOIN users u ON u.id=a.requested_by LEFT JOIN users d ON d.id=a.decided_by WHERE a.company_id=?`,alias:'a',columns:[['审批编号','document_no'],['业务类型','object_type'],['业务ID','object_id'],['申请原因','reason'],['申请人','requester_name'],['当前角色','assigned_role'],['状态','status'],['审批意见','decision_note'],['决定人','decider_name'],['申请时间','created_at'],['决定时间','decided_at']]}
