  const config=configs[module];assert(config,404,'不支持此导出模块');const scope=config.owner?scopeFilter(user,config.owner):{sql:'',params:[]};const rows=list(`${config.sql}${scope.sql} ORDER BY ${config.alias}.created_at DESC`,[user.company_id,...scope.params]).filter(row=>ids.includes(row.id));assert(rows.length===ids.length,404,'部分记录不存在或不在当前数据范围');
  if(module==='quotes'||module==='orders'){const quote=module==='quotes',itemTable=quote?'quote_items':'sales_order_items',foreignKey=quote?'quote_id':'sales_order_id';const expanded=[];for(const record of rows){const items=list(`SELECT i.*,p.sku FROM ${itemTable} i LEFT JOIN products p ON p.id=i.product_id WHERE i.${foreignKey}=? ORDER BY ${quote?'i.sort_order':'i.id'}`,[record.id]);for(const item of items)expanded.push({document_no:record.document_no,customer_name:record.customer_name,sku:item.sku||'',description:item.description,quantity:item.quantity,unit_price:item.unit_price,unit_cost:item.unit_cost,line_amount:Number(item.quantity)*Number(item.unit_price),currency:record.currency,incoterm:record.incoterm,payment_terms:record.payment_terms,delivery_at:record.delivery_at,valid_until:record.valid_until,status:record.status});}return {columns:[[quote?'PI编号':'SO编号','document_no'],['客户','customer_name'],['SKU','sku'],['产品描述','description'],['数量','quantity'],['销售单价','unit_price'],['单位成本','unit_cost'],['行金额','line_amount'],['币种','currency'],['贸易条款','incoterm'],['付款条款','payment_terms'],['交期','delivery_at'],...(quote?[['有效期','valid_until']]:[]),['状态','status']],rows:expanded,recordCount:rows.length};}
